"""Portable local candidate review; no external scripts or automatic claim writes."""
from __future__ import annotations
import json
from pathlib import Path


def write_review(folder: Path) -> Path:
    summary=json.loads((folder/'summary.json').read_text())
    runs={name:json.loads((folder/(name+'.json')).read_text()) for name in summary['runs']}
    # Pack repeated column names once and keep source details in linked JSON.
    for name, run in list(runs.items()):
        columns = list(run['ranking'][0]) if run['ranking'] else []
        runs[name] = {key: run[key] for key in ['configuration', 'statistics', 'content_hash']}
        runs[name]['evaluation'] = {key: run['evaluation'][key] for key in ['matched_count', 'total_controls']}
        runs[name]['columns'] = columns
        runs[name]['values'] = [[row.get(key) for key in columns] for row in run['ranking']]
    compact_summary = {'comparisons': {key: {k:v for k,v in value.items() if k != 'top_changes'} for key,value in summary['comparisons'].items()}}
    payload=json.dumps({'summary':compact_summary,'runs':runs},ensure_ascii=True,allow_nan=False,separators=(',', ':')).replace('<','\\u003c')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Microglia candidate review</title><style>
:root{font:16px system-ui;color:#173038;background:#f4f6f4}body{margin:0}main{max-width:1350px;margin:auto;padding:30px}h1{font-size:34px;letter-spacing:-1px;margin:10px 0}h2{font-size:19px}p{line-height:1.55}.eyebrow{font-size:12px;letter-spacing:2px;color:#49696b}.notice{padding:15px 20px;border-left:4px solid #ba7737;background:#fff4df}.cards{display:flex;gap:14px;margin:24px 0;flex-wrap:wrap}.card{background:white;padding:18px 24px;border:1px solid #d8e1dc;border-radius:8px;min-width:160px}.card strong{display:block;font-size:30px}label{display:inline-flex;flex-direction:column;gap:6px;font-size:13px;margin:0 12px 14px 0}input,select,textarea,button{font:inherit;padding:10px;border:1px solid #a6b9b5;border-radius:5px;background:white;color:inherit}button{cursor:pointer;background:#e8f1ed}button:hover{background:#cfe4dd}a{color:#246b62}table{border-collapse:collapse;width:100%;font-size:13px;background:white}th,td{text-align:left;padding:12px;border-bottom:1px solid #e0e7e3}th{background:#e6ede8;white-space:nowrap}.scroll{overflow:auto}td button{border:0;background:none;padding:0;color:#17655c;text-align:left}#detail{background:white;padding:22px;border:1px solid #d5dfd9;margin-top:20px;border-radius:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}textarea{width:95%;min-height:80px}.muted{color:#58716f;font-size:13px}#count{margin:10px 0}.toolbar{margin-top:22px}@media(max-width:650px){main{padding:18px}h1{font-size:28px}.card{min-width:115px;padding:12px}label{width:100%}}
</style><main><div class="eyebrow">TITANS MED · RESEARCH REVIEW</div><h1>Microglia candidate review</h1><p>Inspect reversal evidence, context dependence and changes between analysis choices.</p><p class="notice">Exploratory hypotheses. LINCS contexts are not microglia assays. No independent rescue or viability validation has been established. FDR applies to the declared aggregate statistic, not selected cells or the best context.</p><div class="cards" id="cards"></div><p class="notice" id="sensitivity"></p><details><summary>Model and overlap sensitivity</summary><pre id="comparison"></pre></details><div class="toolbar"><label>Analysis<select id="run"></select></label><label>Compound or identifier<input id="search" type="search" placeholder="Search compounds"></label><label>Coverage<select id="coverage"><option value="scored">Scored only</option><option value="all">All candidates</option></select></label><label>Reversal<select id="direction"><option value="all">All directions</option><option value="positive">Positive only</option></select></label><label>Sort<select id="sort"><option value="rank">Engine rank</option><option value="score">Reversal score</option><option value="fdr">FDR</option></select></label></div><p id="count" class="muted"></p><div class="scroll"><table><thead><tr><th>Rank</th><th>Candidate</th><th>Score</th><th>FDR</th><th>Coverage</th><th>Context stability</th><th>Mechanism flag</th></tr></thead><tbody id="rows"></tbody></table></div><section id="detail"><h2>Candidate evidence</h2><p>Select a candidate to inspect its evidence and record a review note.</p></section><p class="muted">Notes stay in this page session until exported. Review notes do not change biological validation or candidate scores. Source metadata and complete rankings are included in each analysis JSON.</p></main>
<script id="payload" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('payload').textContent), notes=[];
for(const run of Object.values(data.runs)){run.ranking=run.values.map(values=>Object.fromEntries(run.columns.map((key,i)=>[key,values[i]])));delete run.values;}
const $=id=>document.getElementById(id);const esc=x=>String(x??'unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=x=>typeof x==='number'?x.toFixed(3):'—';let current, visible;
for(const key of Object.keys(data.runs)){const option=document.createElement('option');option.value=key;option.textContent=key.replaceAll('_',' ');$('run').append(option)}
$('run').value='context_mix';
$('comparison').textContent=JSON.stringify(Object.fromEntries(Object.entries(data.summary.comparisons).map(([k,v])=>[k,{common_scored:v.common_scored,top25_overlap:v.top25_overlap,score_rank_correlation:v.score_rank_correlation,interpretation:v.interpretation}])),null,2);
function score(row){return row.connectivity_mean??row.cosine_reversal}
function render(){current=data.runs[$('run').value];let ranked=current.ranking.map((r,i)=>({...r,rank:i+1}));let scored=ranked.filter(r=>r.status==='scored');$('sensitivity').textContent=$('run').value==='context_mix'?'Default mixed-model screen. '+scored.filter(r=>score(r)>0&&r.fdr!==null&&r.fdr<=0.25).length+' positive candidates meet exploratory FDR ≤ 0.25.':'Sensitivity or separate-panel analysis. Changing overlap, model or panel changes the testing family; these are not independent confirmations.';$('cards').innerHTML=`<div class="card"><strong>${ranked.length}</strong>perturbations</div><div class="card"><strong>${scored.length}</strong>meet coverage</div><div class="card"><strong>${current.configuration.n_perm}</strong>permutations</div><div class="card"><strong>${current.evaluation.matched_count}/${current.evaluation.total_controls}</strong>exploratory controls matched</div>`;
let query=$('search').value.toLowerCase();visible=ranked.filter(r=>($('coverage').value==='all'||r.status==='scored')&&($('direction').value==='all'||score(r)>0)&&[r.pert_iname,r.pert_id,r.cmap_name].join(' ').toLowerCase().includes(query));
if($('sort').value==='score')visible.sort((a,b)=>(score(b)??-Infinity)-(score(a)??-Infinity));if($('sort').value==='fdr')visible.sort((a,b)=>(a.fdr??Infinity)-(b.fdr??Infinity));$('count').textContent=`${visible.length} matching candidates · showing ${Math.min(100,visible.length)} · complete ranking in analysis JSON`;
$('rows').innerHTML=visible.slice(0,100).map((r,i)=>`<tr><td>${r.rank}</td><td><button data-row="${i}">${esc(r.pert_iname??r.cmap_name)}</button><br><small>${esc(r.pert_id??'consensus')}</small></td><td>${number(score(r))}</td><td>${number(r.fdr)}</td><td>${r.n_contexts_scored!==undefined?esc(r.n_contexts_scored)+' contexts':esc(r.overlap)+' genes'}</td><td>${esc(r.context_robustness_status??'consensus; context unresolved')}</td><td>${r.tox_flag?'Flagged':r.moa==='unknown'?'Unknown':'No listed flag'}</td></tr>`).join('');
$('rows').querySelectorAll('button').forEach(button=>button.onclick=()=>detail(visible[Number(button.dataset.row)]));$('detail').innerHTML='<h2>Candidate evidence</h2><p>Select a candidate to inspect its evidence and record a review note.</p>'}
function detail(row){$('detail').innerHTML=`<h2>${esc(row.pert_iname??row.cmap_name)}</h2><p><a href="${esc($('run').value)}.json">Analysis JSON and source hashes</a> · ${esc(current.statistics.tested_statistic)}</p><p class="notice">${row.tox_flag?'Mechanism toxicity flag present. ':''}Viability untested. Best-context and cell-balanced scores are descriptive; their own significance has not been tested.</p><details open><summary>Identity, coverage and context evidence</summary><pre>${esc(JSON.stringify(row,null,2))}</pre></details><label>Review status<select id="status"><option>Needs evidence</option><option>Plan experiment</option><option>Deprioritize</option><option>Observed result</option></select></label><label>Reference or assay receipt<input id="reference" placeholder="DOI, assay ID or local receipt"></label><textarea id="note" aria-label="Review note" placeholder="Observation, contradiction, or next falsification experiment"></textarea><p><button id="export">Export review note</button></p><div id="export-result"></div>`;
$('export').onclick=()=>{const note={schema:'repurposing-review-note/v1',run_hash:current.content_hash,candidate_id:row.pert_id??row.cmap_name,status:$('status').value,reference:$('reference').value,note:$('note').value,recorded_at:new Date().toISOString(),biological_validation_changed:false};notes.push(note);$('export-result').innerHTML='<p>Review JSON prepared. Copy this text if your browser does not save the download.</p><textarea aria-label="Exported review JSON" readonly></textarea>';$('export-result').querySelector('textarea').value=JSON.stringify(notes,null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(notes,null,2)],{type:'application/json'}));a.download='microglia-review-notes.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}}
for(const id of ['run','coverage','direction','sort'])$(id).onchange=render;$('search').oninput=render;render();
</script></html>'''.replace('PAYLOAD',payload)
    target=folder/'index.html';target.write_text(html)
    return target
